                        return inn.newError(errorMessage);
                    }
                    
                    Item idt0 = h4_AppWFGrForDATFormatEXPCLN.getItemByIndex(i).getRelatedItem();//ユーザー取得
                    if (idt0.getProperty("is_alias", "") != "1")
                    {
                            //ユーザーではない
                            continue;
                    }
                    
                    //エイリアスアイデンティティだけが担当者に設定される
                    Item ccAlias = inn.newItem("Alias","get");
                    ccAlias.setProperty("related_id",h4_AppWFGrForDATFormatEXPCLN.getItemByIndex(i).getProperty("related_id"));
                    ccAlias = ccAlias.apply();
                    Item ccUser = inn.newItem("User","get");
                    ccUser.setAttribute("id",ccAlias.getProperty("source_id"));
                    ccUser = ccUser.apply();
                    
                    if(h4_AppWFGrForDATFormatEXPCLN.getItemByIndex(i).getProperty("h4_workflow_role") == "InspEXPStaff")
                    {
                        EXPTestCreaterList.Add(ccUser.getProperty("email"));
                        isExist_Creater = true;
                        if(ccUser.getProperty("email","") == ""){ noMailUser.Add(ccUser.getProperty("keyed_name",""));}
                    }
                    else if(h4_AppWFGrForDATFormatEXPCLN.getItemByIndex(i).getProperty("h4_workflow_role") == "InspEXPApprover")
                    {
                        EXPTestApproverList.Add(ccUser.getProperty("email"));
                        isExist_Reviewer = true;
                        if(ccUser.getProperty("email","") == ""){ noMailUser.Add(ccUser.getProperty("keyed_name",""));}
                    }
                    else if(h4_AppWFGrForDATFormatEXPCLN.getItemByIndex(i).getProperty("h4_workflow_role") == "Q1Staff")
                    {
                        Q1CreaterList.Add(ccUser.getProperty("email"));
                        isExist_Approver = true;
                        if(ccUser.getProperty("email","") == ""){ noMailUser.Add(ccUser.getProperty("keyed_name",""));}
                    }
                    else if(h4_AppWFGrForDATFormatEXPCLN.getItemByIndex(i).getProperty("h4_workflow_role") == "Q1Approver")
                    {
                        Q1ApproverList.Add(ccUser.getProperty("email"));
                        isExist_Approver = true;
                        if(ccUser.getProperty("email","") == ""){ noMailUser.Add(ccUser.getProperty("keyed_name",""));}
                    }
                    else if(h4_AppWFGrForDATFormatEXPCLN.getItemByIndex(i).getProperty("h4_workflow_role") == "ReleaseApprover")
                    {
                        releaseApproverList_EXP.Add(ccUser.getProperty("email"));
                        isExist_Approver = true;
                        if(ccUser.getProperty("email","") == ""){ noMailUser.Add(ccUser.getProperty("keyed_name",""));}
                    }
                }
            }
            else//EXP検定以外
            {
                Item h4_AppWFGrForDATFormatCLN = inn.newItem("h4_AppWFGrForDATFormat CLN","get");
                h4_AppWFGrForDATFormatCLN.setProperty("source_id",workflowSourceId);
                h4_AppWFGrForDATFormatCLN.setAttribute("select","related_id,h4_workflow_role");
                h4_AppWFGrForDATFormatCLN = h4_AppWFGrForDATFormatCLN.apply();
                
                if(h4_AppWFGrForDATFormatCLN.isError() && h4_AppWFGrForDATFormatCLN.getItemCount() == -1)
                {
                    //エラー
                    errorMessage = CCO.ErrorLookup.Lookup("h4_S_E_0002");
                    return inn.newError(errorMessage);
                }
                
                for(int i = 0;i < h4_AppWFGrForDATFormatCLN.getItemCount();i++)
                {
                    //related_idが存在しない場合はエラーとする
                    var related_id = h4_AppWFGrForDATFormatCLN.getItemByIndex(i).getProperty("related_id","");
                    if(string.IsNullOrEmpty(related_id))
                    {
                        return inn.newError(CCO.ErrorLookup.Lookup("h4_S_E_0005"));
                    }
    
                    Item Identity = inn.newItem("Identity","get");
                    Identity.setProperty("id",h4_AppWFGrForDATFormatCLN.getItemByIndex(i).getProperty("related_id"));
                    Identity = Identity.apply();
                    
                    if(Identity.isError() && Identity.getItemCount() == -1)
                    {
                        //エラー
                        errorMessage = CCO.ErrorLookup.Lookup("h4_S_E_0002");
                        return inn.newError(errorMessage);
                    }
                    
                    Item idt0 = h4_AppWFGrForDATFormatCLN.getItemByIndex(i).getRelatedItem();//ユーザー取得
                    if (idt0.getProperty("is_alias", "") != "1")
                    {
                            //ユーザーではない
                            continue;
                    }
                    
                    //エイリアスアイデンティティだけが担当者に設定される
                    Item ccAlias = inn.newItem("Alias","get");
                    ccAlias.setProperty("related_id",h4_AppWFGrForDATFormatCLN.getItemByIndex(i).getProperty("related_id"));
                    ccAlias = ccAlias.apply();
                    Item ccUser = inn.newItem("User","get");
                    ccUser.setAttribute("id",ccAlias.getProperty("source_id"));
                    ccUser = ccUser.apply();
                    
                    if(h4_AppWFGrForDATFormatCLN.getItemByIndex(i).getProperty("h4_workflow_role") == "Creater")
                    {
                        createrList.Add(ccUser.getProperty("email"));
                        isExist_Creater = true;
                        if(ccUser.getProperty("email","") == ""){ noMailUser.Add(ccUser.getProperty("keyed_name",""));}
                    }
                    else if(h4_AppWFGrForDATFormatCLN.getItemByIndex(i).getProperty("h4_workflow_role") == "ReleaseApprover")
                    {
                        releaseApproverList.Add(ccUser.getProperty("email"));
                        isExist_Reviewer = true;
                        if(ccUser.getProperty("email","") == ""){ noMailUser.Add(ccUser.getProperty("keyed_name",""));}
                    }
                    else if(h4_AppWFGrForDATFormatCLN.getItemByIndex(i).getProperty("h4_workflow_role") == "Approver")
                    {
                        approverList.Add(ccUser.getProperty("email"));
                        isExist_Approver = true;
                        if(ccUser.getProperty("email","") == ""){ noMailUser.Add(ccUser.getProperty("keyed_name",""));}
                    }
                }
            }

            Item appWFGroupPointOuts = inn.newItem("h4_AppWFGr4DATFormat PointOut","get");
            appWFGroupPointOuts.setProperty("source_id",workflowSourceId);
            appWFGroupPointOuts.setAttribute("select", "related_id");
            appWFGroupPointOuts = appWFGroupPointOuts.apply();

            if(appWFGroupPointOuts.isError() && appWFGroupPointOuts.getItemCount() == -1)
            {
                //エラー
                errorMessage = CCO.ErrorLookup.Lookup("h4_S_E_0002");
                return inn.newError(errorMessage);
            }

            int prefixStringNum = 4;//接頭語 APD_
            for(int i = 0; i < appWFGroupPointOuts.getItemCount(); i++)
            {
                Item tempPointOut = inn.newItem("h4_PointOut","get");
                tempPointOut.setProperty("id",appWFGroupPointOuts.getItemByIndex(i).getProperty("related_id"));
                tempPointOut.setAttribute("select", "h4_point_number");
                tempPointOut = tempPointOut.apply();

                if(tempPointOut.isError() && tempPointOut.getItemCount() == -1)
                {
                    //エラー
                    errorMessage = CCO.ErrorLookup.Lookup("h4_S_E_0002");
                    return inn.newError(errorMessage);
                }

                string temph4PointNumber = tempPointOut.getProperty("h4_point_number");
                temph4PointNumber = temph4PointNumber.Substring(prefixStringNum);
                int.TryParse(temph4PointNumber,out int tempPointNumber);

                if(pointNumber == 0)
                {
                    pointNumber = tempPointNumber;
                }

                if(pointNumber < tempPointNumber)
                {
                    pointNumber = tempPointNumber;
                }
            }

            pointNumber += 1;
            
        }

        // メールが空欄のユーザーがいるならエラー
        if(noMailUser.Count != 0)
        {
            noMailUser = noMailUser.Distinct().ToList();
            string userNameForMessage = string.Join("<br>", noMailUser);
            return inn.newError(CCO.ErrorLookup.Lookup("h4_S_E_0013",userNameForMessage));
        }

        itemType = inn.newItem("ItemType","get");
        itemType.setProperty("id",workflowSourceType);
        itemType.setAttribute("select", "label,name");
        itemType = itemType.apply();
        itemTypeLabel = itemType.getProperty("label");

        if((workflowSourceType == "018E955AA0DC4FAFBDE9BDC651E3188A") && (pathName == "Reject" || pathName == "reject"))
        {
            string approveItemEvent = approveItem.getProperty("h4_event","");
            string approveItemMy = approveItem.getProperty("h4_my","");
            string approveItemDestination = approveItem.getProperty("h4_destination","");
            string approveItemDeltaVersion = approveItem.getProperty("h4_delta_version","");
            string approveItemModelName = approveItem.getProperty("h4_model_name","");
            string managedById = approveItem.getProperty("managed_by_id","");
            string evaluationUnit = approveItem.getProperty("h4_evaluation_unit","");
            string uniqueEvent = approveItem.getProperty("h4_unique_event","");
            string closedDate = DateTime.Now.ToString("yyyy-MM-ddTHH:mm:ss");
            string pointOutId = inn.getNewID();

            Item pointOut = inn.newItem("h4_PointOut","add");
            pointOut.setID(pointOutId);
            pointOut.setProperty("h4_event",approveItemEvent);
            pointOut.setProperty("h4_my",approveItemMy);
            pointOut.setProperty("h4_destination",approveItemDestination);
            pointOut.setProperty("h4_delta_version",approveItemDeltaVersion);
            pointOut.setProperty("h4_indication_date",closedDate);
            pointOut.setProperty("h4_pointer",currentUserId);
            pointOut.setProperty("h4_newest_pointout",pointOutId);
            pointOut.setProperty("h4_model_name",approveItemModelName);
            pointOut.setProperty("managed_by_id",managedById);
            pointOut.setProperty("h4_evaluation_unit",evaluationUnit);
            pointOut.setProperty("h4_unique_event",uniqueEvent);
            pointOut.setProperty("h4_rel_appwfgroupfordatformat",workflowSourceId);
            pointOut.setProperty("h4_point_number","APD_" + pointNumber.ToString("D3"));
            pointOut.setProperty("h4_points_to_note",comment);
            pointOut = pointOut.apply();

            if(pointOut.isError() && pointOut.getItemCount() == -1)
            {
                //エラー
                errorMessage = CCO.ErrorLookup.Lookup("h4_S_E_0002");
                return inn.newError(errorMessage);
            }

            Item appWFGroupPointOut = inn.newItem("h4_AppWFGr4DATFormat PointOut","add");
            appWFGroupPointOut.setProperty("source_id",workflowSourceId);
            appWFGroupPointOut.setProperty("related_id",pointOut.getProperty("id"));
            appWFGroupPointOut = appWFGroupPointOut.apply();

            if(appWFGroupPointOut.isError() && appWFGroupPointOut.getItemCount() == -1)
            {
                //エラー
                errorMessage = CCO.ErrorLookup.Lookup("h4_S_E_0002");
                return inn.newError(errorMessage);
            }
        }
        
        // //メールアイテム作成
        string mailItemName = "h4_WFMail";
        if(pathName == "Reject"||pathName == "reject")
        {
            mailItemName = "h4_WFMailReject";
        }
        else if(pathName == "Approve")
        {
            mailItemName = "h4_WFMailApprove";
        }
        else//その他は共通にしている
        {
            mailItemName = "h4_WFMail";
        }
        Item mailItem = inn.newItem("EMail Message","get");
        mailItem.setProperty("name",mailItemName);
        mailItem = mailItem.apply();
        
        if(mailItem.isError() && mailItem.getItemCount() == -1)
        {
            //エラー
            errorMessage = CCO.ErrorLookup.Lookup("h4_S_E_0002");
            return inn.newError(errorMessage);
        }
        
        string tempRequest = pathLabel.Replace("仮","");
        string Request = tempRequest.Replace("依頼","");
        string mailBody = mailItem.getProperty("body_html");
        
        if((workflowSourceType == "018E955AA0DC4FAFBDE9BDC651E3188A" && pathName == "Reject") || (workflowSourceType == "018E955AA0DC4FAFBDE9BDC651E3188A" && pathName == "reject"))//一括承認否認の場合
        {
            mailBody = mailBody.Replace("{ItemName}","承認対象アイテム");
        }
        else
        {
            mailBody = mailBody.Replace("{ItemName}",itemTypeLabel);
        }
        
        // サーバー情報を取得
        string hostString = CCO.Request.Host.Value;
        string dbString = CCO.Request.PathBase.Value;
        // 末尾のServer文字列を削除
        char[] serverChar = new char[6]{'r', 'e', 'v', 'r', 'e', 'S'};
        
        foreach (char sChar in serverChar)
        {
             dbString = dbString.TrimEnd(sChar);
        }
        
        string serverURL = CCO.Request.Scheme + "://" + hostString + dbString;
        mailBody = mailBody.Replace("{Request}",Request);
        mailBody = mailBody.Replace("{KeyName}",keyName);
        mailBody = mailBody.Replace("{ItemURL}",serverURL+"?StartItem="+approveItemType+"%3A"+workflowSourceId);
        string tmpmailComment = "";
        if(userCommentList.Count >= 1 ){tmpmailComment = string.Join("",userCommentList)+"<br>";} 
        mailBody = mailBody.Replace("{UserComment}",tmpmailComment);
        mailItem.setProperty("body_html",mailBody);
        string subject = mailItem.getProperty("subject");
        subject = subject.Replace("{Path}",pathLabel);
        subject = subject.Replace("{KeyName}",keyName);
        mailItem.setProperty("subject",subject);
        
        //送信元アドレスを取得
        string fromUserID = mailItem.getProperty("from_user");
        Item fromUser = inn.newItem("User","get");
        fromUser.setAttribute("id",fromUserID);
        fromUser.setAttribute("select","email");
        fromUser = fromUser.apply();
        string fromAddress = fromUser.getProperty("email");
        
        //メール送信メソッドh4_sendMail_DATへ送信するメールと送信先アイデンティティのリスト、送信先アクティビティを渡す
        RequestState.Add("expFlag",expFlag);
        RequestState.Add("Subject",mailItem.getProperty("subject"));
        RequestState.Add("Body",mailItem.getProperty("body_html"));
        RequestState.Add("fromAddress",fromAddress);//from
        RequestState.Add("createrList",createrList);//to&cc
        RequestState.Add("releaseApproverList",releaseApproverList);
        RequestState.Add("approverList",approverList);
        RequestState.Add("EXPTestCreaterList",EXPTestCreaterList);
        RequestState.Add("EXPTestApproverList",EXPTestApproverList);
        RequestState.Add("Q1CreaterList",Q1CreaterList);
        RequestState.Add("Q1ApproverList",Q1ApproverList);
        RequestState.Add("releaseApproverList_EXP",releaseApproverList_EXP);
        RequestState.Add("nextActivity",relatedActivity.getProperty("name"));//遷移先
        RequestState.Add("targetItemId",workflowSourceId);//承認対象アイテムのID
    }
}
return this;
